INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل تثبيت لولب 90 ملم في الري بالتنقيط والشريط' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعلم كيفية تثبيت لولب 90 ملم في أنظمة الري بالتنقيط والشريط بفاعلية. دليل فني دقيق للمزارعين العراقيين يركز على تحسين كفاءة الري وتقليل الهدر مع الحفاظ على دقة المصطلحات الفنية مثل AFP.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
