INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақолаи муфассал оид ба интихоби навари тиби барои овории нил, маълумот оид ба ҳисобкуниҳо, насб ва беҳтар кардани истифодабарии обро меомӯзед. Барои кишоварони нил, ин равеш ёри мекунад, то бизоҳан овории самаранок ва ҳамоиштаи абйорро анҷом диҳанд.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
